suppressPackageStartupMessages({library(data.table);library(ggplot2);library(grid)});setDTthreads(1);B='/home/data/t070721/codex_workspace/Bladder Metabolism/results/mp10_resistance_validation_v2_expanded';sk='/home/data/t070721/.agents/skills/jins-routine-plotting';for(f in c('common/theme.R','common/palettes.R','common/export.R'))source(file.path(sk,f));jin_setup();rd=function(p)fread(file.path(B,p));out=file.path(B,'07_summary/figures');dir.create(out,recursive=TRUE,showWarnings=FALSE);index=list();cols=c(parental='#808080',CisR='#d45087',GemCisR='#984ea3',GemR='#377eb8',GemR_P3='#56B4E9',GemR_P7='#0072B2',GemR_P15='#009E73',Response='#377eb8',Nonresponse='#d45087',raw='#808080',depth_only='#009E73',depth_cycle='#d45087',nFeature_cycle='#377eb8');short=function(s)gsub('_',' ',gsub('CISPLATIN_RESISTANCE_','',gsub('HALLMARK_','HM ',s)))
ex=function(p,name,w,h,source,note=''){jin_export(p+theme(axis.line=element_line(linewidth=.4)),file.path(out,name),w,h);index[[length(index)+1]]<<-data.table(figure=name,source=source,note=note,width=w,height=h);cat('FIGURE',name,'\n')}
